// BỘ MẪU SLIDE của tầng hình ảnh — mỗi type của deck.json thành một khối HTML 1920×1080 (CSS ở stage.css); hinh/dung.js gọi, hinh/build.js chuyển thành PPTX.
// Dùng lại đúng các trường của deck.json mà engine PPTX đang đọc; type chưa có mẫu riêng thì rơi về `generic` và build báo tên.
const React = require("react");
const Server = require("react-dom/server");
const PACKS = ["fa6", "fa", "pi", "lu", "tb"].map((p) => { try { return require("react-icons/" + p); } catch { return {}; } });

const esc = (s) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const f = (s) => esc(s).replace(/\[([^\]]+)\]/g, "<em>$1</em>").replace(/\n/g, "<br>");   // "\n" trong chuỗi = xuống dòng chủ ý (ngắt tại nghĩa)          // [từ khoá] → nhấn
const plain = (s) => String(s ?? "").replace(/[[\]]/g, "");
const ico = (name) => { for (const p of PACKS) if (name && p[name]) return `<span class="ico">${Server.renderToStaticMarkup(React.createElement(p[name]))}</span>`; return ""; };
let I = 0;
const inn = (kind) => `data-in${kind ? `="${kind}"` : ""} style="--i:${I++}"`;   // thứ tự vào (thành hiệu ứng vào lần lượt trong PowerPoint)
const head = (s, c = "") => `${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}${s.title ? `<h2 class="h ${c} ${plain(s.title).length > 54 ? "sm" : ""}" ${inn()}>${f(s.title)}</h2>` : ""}`;
const note = (t) => (t ? `<p class="note" ${inn()}>${f(t)}</p>` : "");
// ✓ ✕ vẽ bằng icon SVG (thành lớp ảnh): Anton / Be Vietnam Pro không có hai ký tự này → trình duyệt, PowerPoint lấy font khác, có máy hiện xám mờ trên ô xanh (soát chi tiết đo 1,47 : 1)
const mark = (ok) => (ok === true || ok === "yes" ? `<span class="ok">${ico("PiCheckBold")}</span>` : ok === false || ok === "no" ? `<span class="no">${ico("PiXBold")}</span>` : ok === "na" ? `<span class="mb">–</span>` : `<span class="mb">?</span>`);
const dmy = (d) => { const m = String(d).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/); return m ? +m[3] + (+m[2] - 1) / 12 + (+m[1] - 1) / 365 : parseFloat(String(d).match(/\d{4}/)?.[0] ?? NaN); };
const days = (a, b) => { const p = (d) => { const m = String(d).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/); return m ? new Date(+m[3], +m[2] - 1, +m[1]) : null; }; const x = p(a), y = p(b); return x && y ? { from: x, n: Math.round((y - x) / 864e5) } : null; };

const T = {};
// khung ảnh (frame / meta.frame): rect bo góc · arch vòm · circle tròn · ogee vòm nhọn — CSS cắt khung, ảnh vẫn là ảnh thật (lớp ảnh trong PowerPoint)
const KHUNG = { rect: "border-radius:28px", arch: "border-radius:999px 999px 18px 18px / 420px 420px 18px 18px", circle: "border-radius:50%", ogee: "clip-path:polygon(50% 0, 66% 6%, 80% 18%, 90% 34%, 96% 52%, 100% 70%, 100% 100%, 0 100%, 0 70%, 4% 52%, 10% 34%, 20% 18%, 34% 6%)" };
const khungAnh = (s, deck) => { const k = s.frame || deck?.meta?.frame; return KHUNG[k] ? k : null; };
const anhKhung = (url, k, alt, st) => `<div class="phk" data-in style="--i:${I++};${st};background-image:url('${url}');${KHUNG[k] || KHUNG.rect}" role="img" aria-label="${esc(alt || "")}"></div>`;   // một thuộc tính style duy nhất (inn() cũng ghi style — hai cái thì trình duyệt bỏ cái sau)
const anhPhu = (url, cls = "") => `<div class="ph-full ${cls}" style="background-image:url('${url}')"></div><div class="ph-shade ${cls}"></div>`;

T.cover = (s, deck, ctx) => {
  const len = plain(s.title).length, fs = len > 62 ? 76 : len > 44 ? 90 : len > 28 ? 108 : 132, photo = ctx.img(s.photo), k = khungAnh(s, deck);
  // bìa poster: ảnh tràn viền phủ tối dần, tiêu đề rất lớn, 1–3 thẻ dữ kiện — đi cặp với end "poster"
  if (photo && (s.layout === "poster" || s.layout === "full")) return { cls: "dark cover poster", bare: true, html: `${anhPhu(photo)}
  <div class="top">${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}</div>
  <div class="mid"><h1 class="h" style="--fs:${fs + 8}px" ${inn()}>${f(s.title)}</h1>${s.subtitle ? `<p class="sub" ${inn()}>${f(s.subtitle)}</p>` : ""}${(s.facts || []).length ? `<div class="facts">${s.facts.slice(0, 3).map((x) => `<span ${inn()}>${f(x)}</span>`).join("")}</div>` : ""}</div>
  <div class="bot who" ${inn()}><div><b>${esc(s.author || deck.meta?.author || "")}</b><span>${esc([s.authorSub, s.date].filter(Boolean).join(" — "))}</span></div></div>` };
  if (photo && k) return { cls: "dark cover", bare: true, html: `${anhKhung(photo, k, s.photoAlt, "position:absolute;right:110px;top:130px;width:640px;height:820px;z-index:2")}
  <div class="top">${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}</div>
  <div class="mid" style="max-width:980px"><h1 class="h" style="--fs:${Math.min(fs, 100)}px" ${inn()}>${f(s.title)}</h1>${s.subtitle ? `<p class="sub" ${inn()}>${f(s.subtitle)}</p>` : ""}</div>
  <div class="bot who" ${inn()}><div><b>${esc(s.author || deck.meta?.author || "")}</b><span>${esc([s.authorSub, s.date].filter(Boolean).join(" — "))}</span></div></div>` };
  return { cls: "dark cover", bare: true, html: `${photo ? `<div class="ph" style="background-image:url('${photo}')"></div><div class="ph-tint"></div><div class="slash"></div>` : `<div class="glyph">§</div>`}
  <div class="top">${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}</div>
  <div class="mid"><h1 class="h" style="--fs:${fs}px" ${inn()}>${f(s.title)}</h1>${s.subtitle ? `<p class="sub" ${inn()}>${f(s.subtitle)}</p>` : ""}</div>
  <div class="bot who" ${inn()}>${s.initials ? `<div class="ini">${esc(s.initials)}</div>` : ""}<div><b>${esc(s.author || deck.meta?.author || "")}</b><span>${esc([s.authorSub, s.date].filter(Boolean).join(" — "))}</span></div></div>` };
};

T.statement = (s) => {
  const st = s.stats || [];
  return { cls: s.mode === "a" ? "red" : "dark", html: `${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}<div class="body">
  <h2 class="h ${plain(s.title).length > 46 ? "" : "xl"}" ${inn()}>${f(s.title)}</h2>${s.sub ? `<p class="sub" ${inn()}>${f(s.sub)}</p>` : ""}
  ${st.length ? `<div class="stats" style="--n:${st.length}">${st.map((x) => `<div class="stat" ${inn()}><div class="l">${f(x.label)}</div><div class="v">${f(x.value)}</div><div class="d">${f(x.desc)}</div></div>`).join("")}</div>` : ""}
  </div>${s.stamp ? `<div class="stamp" style="right:130px;top:190px" ${inn("pop")}>${esc(s.stamp)}</div>` : ""}` };
};
T.quote = (s) => ({ cls: "dark", html: `${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}<div class="body"><h2 class="h" ${inn()}>“${f(s.quote || s.title)}”</h2>${s.by ? `<p class="sub" ${inn()}>${f(s.by)}${s.role ? `, ${f(s.role)}` : ""}</p>` : ""}</div>` });

T.agenda = (s, deck, ctx) => { const ph = ctx && ctx.img(s.photo); if (ph) return { cls: "light", html: `${head(s)}<div class="body"><div class="ag-ph"><div>${(s.items || []).map((x, i) => `<div class="ag-row" ${inn()}><div class="ag-no">${String(i + 1).padStart(2, "0")}</div><div class="ag-t" style="font-size:38px">${f(typeof x === "string" ? x : x.text || x.title)}</div></div>`).join("")}</div>${anhKhung(ph, khungAnh(s, deck) || "arch", s.photoAlt, "width:520px;height:640px")}</div></div>` };
  return T.agendaChu(s); };
T.agendaChu = (s) => ({ cls: "light", html: `${head(s)}<div class="body"><div>${(s.items || []).map((x, i) => `<div class="ag-row" ${inn()}><div class="ag-no">${String(i + 1).padStart(2, "0")}</div><div class="ag-t">${f(typeof x === "string" ? x : x.text || x.title)}</div></div>`).join("")}</div></div>` });

T.section = (s, deck, ctx) => { const ph = ctx && ctx.img(s.photo);
  const chu = secChu(s);
  if (ph && s.photoLayout === "backdrop") return { cls: "red sec sec-ph", html: `${anhPhu(ph, "ph-nhoe")}<div class="big">${esc(s.num ?? "")}</div><div class="body">${chu}</div>` };
  if (ph) return { cls: "red sec sec-ph", html: `${anhKhung(ph, khungAnh(s, deck) || "rect", s.photoAlt, "position:absolute;right:110px;top:150px;width:700px;height:800px;z-index:2")}<div class="body" style="max-width:900px">${chu}</div>` };
  return T.sectionChu(s); };
T.sectionChu = (s) => ({ cls: "red sec", html: `<div class="big">${esc(s.num ?? "")}</div><div class="body">${secChu(s)}</div>` });
// chữ của slide chương: nhãn = kicker, hoặc "Phần N · part"; inside = các mục trong phần (người nghe biết phần này gồm gì)
function secChu(s) { const nhan = s.kicker ? f(s.kicker) : [s.num != null ? `Phần ${esc(s.num)}` : "", s.part ? f(s.part) : ""].filter(Boolean).join(" · ");
  return `${nhan ? `<div class="k" ${inn()}>${nhan}</div>` : ""}<h2 class="h" ${inn()}>${f(s.title)}</h2>${s.sub ? `<p class="sub" ${inn()}>${f(s.sub)}</p>` : ""}${(s.inside || []).length ? `<ul class="sec-in">${s.inside.slice(0, 5).map((x) => `<li ${inn()}>${f(x)}</li>`).join("")}</ul>` : ""}`; }

const timelineStrip = (pts, active) => `<div class="tl" ${inn()}>${pts.map((p, i) => { const x = ((i + 0.5) / pts.length * 100).toFixed(2), on = active.includes(i) ? "on" : ""; return `<i class="${on}" style="left:${x}%"></i><span class="${on}" style="left:${x}%">${esc(on ? p[0] : p[1] || p[0])}</span>`; }).join("")}</div>`;
T.scene = (s, deck) => {
  const pts = s.timeline && deck.timelines?.[s.timeline.ref], ev = s.events || [];
  return { cls: "light", html: `<div class="sc-top">${s.year ? `<div class="yr" ${inn("pop")}>${esc(s.year)}</div>` : "<span></span>"}<div>${head(s)}${s.sum ? `<p class="sub" ${inn()}>${f(s.sum)}</p>` : ""}</div></div>
  <div class="body">${pts ? timelineStrip(pts, s.timeline.active || []) : ""}<div class="evs" style="--n:${Math.max(ev.length, 2)}">${ev.map((e) => `<div class="card ev" ${inn()}><div class="d">${esc(e.date || e.when || "")}</div><div class="t">${f(e.text)}</div></div>`).join("")}</div></div>` };
};
T.steps = (s) => { const it = s.items || s.steps || []; return { cls: "light", html: `${head(s)}<div class="body"><div class="evs" style="--n:${Math.min(Math.max(it.length, 2), 5)}">${it.map((e, i) => `<div class="card ev" ${inn()}><div class="w">${esc(e.when || "")}</div><div class="d">${String(i + 1).padStart(2, "0")}</div><div class="t"><b>${f(e.head || e.name || e.title || "")}</b>${e.desc || e.text ? `<br>${f(e.desc || e.text)}` : ""}</div></div>`).join("")}</div></div>${note(s.note || s.takeaway)}` }; };
T.timeline = (s) => { const it = s.items || s.events || []; return { cls: "light", html: `${head(s)}<div class="body"><div class="evs" style="--n:${Math.min(Math.max(it.length, 2), 5)}">${it.map((e) => `<div class="card ev" ${inn()}><div class="d">${esc(e.when || e.date || "")}</div><div class="t"><b>${f(e.head || e.title || "")}</b>${e.desc || e.text ? `<br>${f(e.desc || e.text)}` : ""}</div></div>`).join("")}</div></div>${note(s.note || s.takeaway)}` }; };

T.flow = (s) => {
  const N = s.nodes || [], W = 1700, x = (i) => (N.length === 1 ? W / 2 : 200 + i * (W - 400) / (N.length - 1)), idx = Object.fromEntries(N.map((n, i) => [n.id, i]));
  const col = { bad: "#e2402a", good: "#2c9566", muted: "#8f866f" };
  let paths = "", labels = "";
  (s.edges || []).forEach((e) => {
    const a = idx[e.from], b = idx[e.to]; if (a == null || b == null) return;
    const up = a < b ? !(e.side === "below") : e.side === "above", gap = Math.abs(b - a), lift = 74 + 46 * gap, y0 = up ? 112 : 508, yc = up ? y0 - lift : y0 + lift, x1 = x(a) + (a < b ? 60 : -60), x2 = x(b) + (a < b ? -60 : 60), c = col[e.tone] || "#0c1222";
    paths += `<path d="M${x1} ${y0} C${x1} ${yc}, ${x2} ${yc}, ${x2} ${y0}" fill="none" stroke="${c}" stroke-width="7" ${e.dash ? 'stroke-dasharray="16 12"' : ""} marker-end="url(#m-${e.tone || "ink"})"/>`;
    labels += `<div class="fl-l ${e.tone || ""}" style="left:${(x1 + x2) / 2}px;top:${up ? y0 - lift * 0.75 : y0 + lift * 0.75}px" ${inn()}>${f(e.label)}</div>`;
  });
  const mk = Object.entries({ ink: "#0c1222", ...col }).map(([k, c]) => `<marker id="m-${k}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="${c}"/></marker>`).join("");
  return { cls: "light", html: `${head(s)}<div class="body"><div class="flow"><svg viewBox="0 0 ${W} 640"><defs>${mk}</defs>${paths}</svg>${N.map((n, i) => `<div class="card fl-n" style="left:${x(i)}px" ${inn()}><div class="pic">${ico(n.icon)}</div>${n.tag ? `<div class="tg">${f(n.tag)}</div>` : ""}<b>${f(n.name)}</b><span>${f(n.who || "")}</span></div>`).join("")}${labels}</div></div>${note(s.note)}` };
};

const li = (x) => `<li ${inn()}><span>${f(typeof x === "string" ? x : x.text || x.head)}</span></li>`;
T.duel = (s) => { const side = (d, c) => `<div class="card ${c}" ${inn()}><h3>${f(d.tag || d.title)}</h3><div class="s2">${f(d.sub || "")}</div><ol>${(d.items || []).map(li).join("")}</ol></div>`; return { cls: "light", html: `${head(s)}<div class="body"><div class="duo">${side(s.left || {}, "l")}${side(s.right || {}, "r")}</div></div>${note(s.footer || s.note)}` }; };
T.compare = (s) => { const side = (d) => `<div class="card ${d.tone || ""}" ${inn()}><h3>${f(d.title)}</h3><div class="tg">${f(d.tag || "")}</div><div class="val">${f(d.value || d.head || "")}</div><p>${f(d.text || "")}</p>${d.note ? `<small>${f(d.note)}</small>` : ""}${(d.items || []).length ? `<ul class="gl">${d.items.map((x) => `<li>${f(typeof x === "string" ? x : x.text)}</li>`).join("")}</ul>` : ""}</div>`; return { cls: "light", html: `${head(s)}<div class="body"><div class="duo cmp">${side(s.left || {})}${side(s.right || {})}</div></div>${note(s.footer || s.note)}` }; };

T.ledger = (s) => {
  const rows = s.rows || [], max = Math.max(1, ...rows.flatMap((r) => (r.steps || []).map((x) => Math.abs(x.value))));
  const fmtN = (v) => (v > 0 ? "+" : v < 0 ? "−" : "") + Math.abs(v).toLocaleString("vi-VN");
  return { cls: "light", html: `${head(s)}<div class="body"><div class="lg-h"><span></span><span style="display:flex;justify-content:space-between"><span>← bỏ ra</span><span>nhận về →</span></span><span style="text-align:right">còn lại${s.unit ? ` (${esc(s.unit)})` : ""}</span></div><div class="lg">${rows.map((r) => {
    const tot = (r.steps || []).reduce((a, x) => a + x.value, 0);
    return `<div class="lg-r ${r.focus ? "on" : ""}" ${inn()}><div><b>${f(r.name)}</b><span>${f(r.sub || "")}</span></div><div class="lg-b">${(r.steps || []).map((x, i) => { const w = (Math.abs(x.value) / max * 46).toFixed(2), top = 4 + i * 52; const lab = `${f(x.label)} ${fmtN(x.value)}`, ins = +w > (plain(x.label).length + 6) * 1.5 + 3; // thanh dài hơn nhãn thì nhãn nằm trong thanh, không thì nằm ngoài đầu thanh
      return x.value < 0 ? `<i class="neg" style="right:50%;width:${w}%;top:${top}px"></i><u class="${ins ? "in" : ""}" style="right:${ins ? "50%" : `calc(50% + ${w}%)`};top:${top}px">${lab}</u>` : `<i class="pos" style="left:50%;width:${w}%;top:${top}px"></i><u class="${ins ? "in" : ""}" style="left:${ins ? "50%" : `calc(50% + ${w}%)`};top:${top}px">${lab}</u>`; }).join("")}</div><div class="lg-t ${tot < 0 ? "neg" : "pos"}">${fmtN(tot)}${r.result ? `<small>${f(r.result)}</small>` : ""}</div></div>`;
  }).join("")}</div></div>${note(s.note)}` };
};

const { veBieuDo } = require("./bieu_do");
// chart: SVG ở stage/bieu_do.js (đủ 10 kind của tầng Office cũ); nguyên nhân tại năm (items[].why) là HỘP CHỮ THẬT dưới biểu đồ, đánh số khớp số tròn trên cột
T.chart = (s) => {
  const ins = s.insight, nWhy = s.kind === "column" ? Math.min(4, (s.items || []).filter((x) => x.why).length) : 0, W = ins ? 1150 : 1700, H = nWhy ? 380 : 520;
  const { svg, why } = veBieuDo(s, W, H);
  const wh = why.length ? `<div class="why" style="--n:${why.length}">${why.map((w, k) => `<div class="card wy" ${inn()}><span class="wn">${k + 1}</span><div><b>${esc(w.label)}</b> ${f(w.text)}</div></div>`).join("")}</div>` : "";
  return { cls: "light", html: `${head(s)}<div class="body"><div class="ch ${ins ? "" : "solo"}"><div class="chw"><div ${inn()}>${svg}</div>${wh}</div>${ins ? `<div class="ins" ${inn("pop")}><div class="v" style="font-size:${[230, 230, 230, 150, 140, 120][plain(String(ins.value)).length] || 100}px">${f(ins.value)}</div><div class="u">${f(ins.unit || "")}</div><p>${f(ins.text || "")}</p></div>` : ""}</div></div>${note(s.note || s.takeaway)}` };
};

T.evidence = (s) => ({ cls: "light", html: `${head(s)}<div class="body"><div class="evd"><div>${s.listTitle ? `<div class="lt" ${inn()}>${f(s.listTitle)}</div>` : ""}<ol class="nl">${(s.items || []).map((x) => `<li ${inn()}><div><b>${f(x.head)}</b><span>${f(x.desc || "")}</span></div></li>`).join("")}</ol></div>
  ${s.quote ? `<div class="doc" ${inn("pop")}>${s.quoteDoc ? `<div class="dh">${esc(s.quoteDoc)}</div>` : ""}<q><mark>${f(s.quote)}</mark></q>${s.quoteBy ? `<div class="by">— ${f(s.quoteBy)}</div>` : ""}</div>` : ""}</div></div>${note(s.foot || s.note)}` });

T.fork = (s) => { const c = s.checklist, br = s.branches || []; return { cls: "light", html: `${head(s)}<div class="body">${(s.axis || []).length ? `<div class="ax" ${inn()}>${s.axis.map((a) => `<div><b>${esc(a[0])}</b>${f(a[1])}</div>`).join("")}</div>` : ""}
  <div class="fk" ${c ? "" : 'style="grid-template-columns:1fr 1fr"'}>${c ? `<div class="card" ${inn()}><h3>${f(c.title)}</h3><ul class="ck">${(c.items || []).map((x) => `<li>${mark(x.ok)}<span>${f(x.text)}</span></li>`).join("")}</ul>${c.q ? `<div class="q">${f(c.q)}</div>` : ""}</div>` : ""}
  ${br.map((b, i) => `<div class="card br ${i === (s.focus ?? 0) ? "on" : ""}" ${inn()}><div class="tg">${f(b.tag)}</div><h3>${f(b.head)}</h3><p>${f(b.text)}</p>${b.src ? `<small>${f(b.src)}</small>` : ""}</div>`).join("")}</div></div>${note(s.footer || s.note)}` }; };

T.bignum = (s) => {
  const d = s.days && days(s.days[0], s.days[1]);
  const strip = d && d.n > 0 && d.n <= 45 ? `<div ${inn()}><div class="days">${Array.from({ length: d.n + 1 }, (_, i) => { const dt = new Date(d.from.getTime() + i * 864e5); return `<i class="${i === 0 || i === d.n ? "on" : ""}">${dt.getDate()}</i>`; }).join("")}</div><div class="dl"><span>${esc(s.daysLabels?.[0] || "")} ${esc(s.days[0])}</span><span>${esc(s.daysLabels?.[1] || "")} ${esc(s.days[1])}</span></div></div>` : "";
  return { cls: "dark", html: `${head(s)}<div class="body"><div class="bn"><div><div class="n" ${inn("pop")}>${f(s.num)}</div><div class="u" ${inn()}>${f(s.unit || "")}</div><div class="nd" ${inn()}>${f(s.numDesc || "")}</div></div>
  <div>${s.condTitle ? `<div class="lt" ${inn()}>${f(s.condTitle)}</div>` : ""}<div class="cds">${(s.conds || []).map((c) => `<div class="cd" ${inn()}>${mark(c.ok)}<div><b>${f(c.head)}</b><span>${f(c.desc || "")}</span></div>${c.verdict ? `<span class="vd">${f(c.verdict)}</span>` : ""}</div>`).join("")}</div>${strip}</div></div></div>${note(s.note)}` };
};
T.hero = (s, deck, ctx) => ({ cls: "dark", html: `${ctx && ctx.img(s.photo) ? anhPhu(ctx.img(s.photo), "toi") : ""}${head(s)}<div class="body"><div class="bn"><div class="n" ${inn("pop")}>${f(s.num ?? s.value)}</div><div><div class="u" ${inn()}>${f(s.unit || "")}</div><div class="nd" ${inn()}>${f(s.text || s.numDesc || s.sub || "")}</div></div></div></div>${note(s.note)}` });

T.panelrows = (s, deck, ctx) => ({ cls: "light", html: `${head(s)}<div class="body"><div class="pr"><div ${inn()}><div class="art ${ctx.img(s.cutout) ? "cut" : ""}">${ctx.img(s.cutout) ? `<img src="${ctx.img(s.cutout)}" alt="${esc(s.cutoutAlt || "")}">` : ico(s.icon) || "§"}${s.stamp ? `<div class="stamp" style="right:-40px;bottom:36px">${esc(s.stamp)}</div>` : ""}</div>${s.artCaption ? `<div class="cap">${f(s.artCaption)}</div>` : ""}</div>
  <div class="rows">${(s.rows || []).map((r) => `<div class="rw ${r.tone || ""}" ${inn()}><b>${f(r.head)}</b><p>${f(r.text || "")}</p>${r.note ? `<small>${f(r.note)}</small>` : ""}</div>`).join("")}</div></div></div>${note(s.note)}` });

T.scorecard = (s) => ({ cls: "light", html: `${head(s)}<div class="body"><table ${inn()}><tr><th></th><th>${f(s.colA || "")}</th><th>${f(s.colB || "")}</th></tr>${(s.rows || []).map((r) => `<tr><td class="q">${f(r.q)}</td>${r.a ? `<td><span class="mk">${mark(true)}</span>${f(r.a)}</td>` : `<td class="e">—</td>`}${r.b ? `<td><span class="mk">${mark(false)}</span>${f(r.b)}</td>` : `<td class="e">—</td>`}</tr>`).join("")}</table></div>${note(s.footer || s.note)}` });
T.table = (s) => { const cols = s.cols || s.columns || [], rows = s.rows || []; return { cls: "light", html: `${head(s)}<div class="body"><table ${inn()}>${cols.length ? `<tr>${cols.map((c) => `<th ${c && c.align === "right" ? 'style="text-align:right"' : ""}>${f(c && typeof c === "object" ? c.label : c)}</th>`).join("")}</tr>` : ""}${rows.map((r, i) => `<tr class="${s.focus === i ? "on" : ""}">${(Array.isArray(r) ? r : r.cells || Object.values(r)).map((c, j) => `<td class="${j === 0 ? "q" : ""}" style="${j === 0 ? "font-size:36px;" : ""}${cols[j] && cols[j].align === "right" ? "text-align:right" : ""}">${f(c)}</td>`).join("")}</tr>`).join("")}</table></div>${note(s.note)}` }; };

T.cards = (s) => { const it = s.items || [], lb = s.labels || []; return { cls: "light", html: `${head(s)}<div class="body"><div class="cg" style="--n:${Math.min(Math.max(it.length, 2), 4)}">${it.map((x) => `<div class="card" ${inn()}><div class="top">${ico(x.icon)}<b>${f(x.name || x.head || x.title)}</b></div><div class="in">${x.tag ? `<div class="tg">${f(x.tag)}</div>` : ""}${x.who ? `${lb[0] ? `<div class="lb">${f(lb[0])}</div>` : ""}<div class="w">${f(x.who)}</div>` : ""}${x.desc || x.text ? `${lb[1] ? `<div class="lb">${f(lb[1])}</div>` : ""}<div class="d">${f(x.desc || x.text)}</div>` : ""}</div></div>`).join("")}</div></div>${note(s.note || s.takeaway)}` }; };
T.stats = (s) => { const st = s.items || s.stats || []; return { cls: "dark", html: `${head(s)}<div class="body"><div class="stats" style="--n:${st.length}">${st.map((x) => `<div class="stat" ${inn()}><div class="l">${f(x.label)}</div><div class="v">${f(x.value)}</div><div class="d">${f(x.desc || "")}</div></div>`).join("")}</div></div>${note(s.note)}` }; };
T.checklist = (s) => ({ cls: "light", html: `${head(s)}<div class="body"><div class="cds">${(s.items || []).map((c) => `<div class="cd" style="background:#fffaf0;border-color:#0c1222" ${inn()}>${mark(c.ok)}<div><b>${f(c.head || c.text)}</b><span>${f(c.desc || (c.head ? c.text : "") || "")}</span></div>${c.verdict || c.src ? `<span class="vd">${f(c.verdict || c.src)}</span>` : ""}</div>`).join("")}</div>${s.verdict && typeof s.verdict === "object" ? `<div class="vdb ${s.verdict.ok === "yes" || s.verdict.ok === true ? "good" : ""}" ${inn("pop")}>${mark(s.verdict.ok)}<div>${f(s.verdict.text)}</div></div>` : ""}</div>${note(typeof s.verdict === "string" ? s.verdict : s.note)}` });

T.photo = (s, deck, ctx) => { const p = ctx.img(s.photo); return { cls: "dark pho", bare: true, html: `${p ? `<div class="img" style="background-image:url('${p}')"></div>` : ""}<div class="tint"></div><div class="in">${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}<h2 class="h" ${inn()}>${f(s.title)}</h2>${s.sub ? `<p class="sub" ${inn()}>${f(s.sub)}</p>` : ""}</div>` }; };

T.closing = (s, deck, ctx) => {
  const ph = ctx && ctx.img(s.photo);
  const ls = (s.lessons || []).length ? `<div class="ls">${s.lessons.map((x) => `<div ${inn()}>${ico(x.icon) || `<span class="ico">■</span>`}<div><b>${f(x.head)}</b><span>${f(x.text || "")}</span></div></div>`).join("")}</div>` : "";
  const right = `${s.verdict ? `<div class="k" ${inn()}>Nhận định</div><div class="vd" ${inn()}>${f(s.verdict)}</div>` : ""}${s.rec ? `<div class="k" ${inn()}>${f(s.rec.title || "Kiến nghị")}</div><ul>${(s.rec.items || []).map((x) => `<li ${inn()}>${f(x)}</li>`).join("")}</ul>` : ""}${s.thanks ? `<div class="th" ${inn()}>${f(s.thanks)}</div>` : ""}`;
  return { cls: "light cl", html: `<div class="g"><div class="l">${head(s)}<div class="an">${(s.answers || []).map((a) => `<div class="${a.tone || ""}" ${inn()}><small>${f(a.q)}</small><p>${f(a.a)}</p></div>`).join("")}</div>${right ? ls : ""}</div>
  <div class="r ${ph && !s.rec ? "rph" : ""}" ${ph && !s.rec ? `style="background-image:linear-gradient(0deg, rgba(12,18,34,.94), rgba(12,18,34,.15) 62%), url('${ph}')"` : ""}>${right || ls}</div></div>` };
};

// lời kết: message (câu chốt) rồi sub (lời mời hỏi đáp…) — trước đây có message thì sub bị bỏ
const endLoi = (s) => [s.message, s.sub].filter(Boolean).map((t) => `<p class="sub" ${inn()}>${f(t)}</p>`).join("");
T.end = (s, deck, ctx) => { const ph = ctx && ctx.img(s.photo);
  if (ph) return { cls: "dark end poster", bare: true, html: `${anhPhu(ph)}${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}<h2 class="h" ${inn()}>${f(s.title || s.thanks || "Cảm ơn")}</h2>${endLoi(s)}${s.teamTitle && (s.team || []).length ? `<p class="tm-t" ${inn()}>${f(s.teamTitle)}</p>` : ""}${(s.team || []).length ? `<div class="facts">${s.team.map((t) => `<span ${inn()}>${esc(typeof t === "string" ? t : t.name)}${t.role ? ` · ${esc(t.role)}` : ""}</span>`).join("")}</div>` : ""}${s.contact ? `<p class="sub" ${inn()}>${esc(s.contact)}</p>` : ""}` };
  return T.endChu(s, deck); };
T.endChu = (s, deck) => ({ cls: "dark end", bare: true, html: `<div class="glyph" style="position:absolute;right:40px;bottom:-150px;font:400 900px/1 var(--fd);color:transparent;-webkit-text-stroke:5px rgba(244,237,220,.14)">?</div>${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}<h2 class="h" ${inn()}>${f(s.title || s.thanks || "Cảm ơn")}</h2>${endLoi(s)}${s.teamTitle && (s.team || []).length ? `<p class="tm-t" ${inn()}>${f(s.teamTitle)}</p>` : ""}${(s.team || []).length ? `<p class="sub" style="margin-top:${s.teamTitle ? 8 : 30}px" ${inn()}>${s.team.map((t) => esc(typeof t === "string" ? t : t.name) + (t.role ? ` (${esc(t.role)})` : "")).join(" — ")}</p>` : ""}${s.contact ? `<p class="sub" ${inn()}>${esc(s.contact)}</p>` : ""}` });

let VN = null;
const fold = (x) => String(x).normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/đ/gi, "d").toLowerCase().replace(/^(tinh|thanh pho|tp\.?)\s+/, "").trim();
T.map = (s) => {
  try { VN = VN || require("../engine/assets/vn_provinces.json"); } catch { return T.generic(s); }
  const PV = s.admin === 63 ? VN.provinces : VN.provinces34, [, , vw, vh] = VN.viewBox, H = 640, OW = H * vw / vh, k = OW / vw, n1 = (v) => v.toFixed(1);
  const P = (lon, lat) => [(lon - VN.lon0) * VN.k * VN.scale, (VN.lat1 - lat) * VN.scale], find = (nm) => Object.entries(PV).find(([n]) => fold(n) === fold(nm));
  const isl = Object.values(VN.islands).flat().map(([lo, la]) => { const [x, y] = P(lo, la); return `<circle cx="${n1(x)}" cy="${n1(y)}" r="5.5" fill="#a7b0c6"/>`; }).join("");
  const islLab = Object.entries(VN.islands).map(([nm, ip]) => { const [x, y] = P(ip.reduce((a, q) => a + q[0], 0) / ip.length, ip.reduce((a, q) => a + q[1], 0) / ip.length), tr = /Trường Sa/.test(nm); return `<text x="${n1(x * k)}" y="${n1(y * k + (tr ? 58 : 40))}" text-anchor="middle" font-size="19" font-style="italic" font-weight="600" fill="#a7b0c6">${esc(nm.replace("Quần đảo", "QĐ."))}</text>`; }).join("");
  const alt = "Bản đồ Việt Nam (gồm quần đảo Hoàng Sa, Trường Sa)";
  if ((s.groups || []).length) {  // tô theo nhóm tỉnh; số tỉnh đếm từ bản đồ, không gõ tay
    const COL = ["#f6b93b", "#e2402a", "#2c9566"], gs = s.groups.slice(0, 3).map((g, i) => ({ g, names: new Set(g.preset ? Object.keys(PV).filter((n) => ((PV[n].from || [n]).length > 1) === (g.preset === "merged")) : (g.provinces || []).map((nm) => (find(nm) || [])[0]).filter(Boolean)), col: g.tone === "bad" ? "#e2402a" : g.tone === "muted" ? "#55607e" : COL[i] }));
    const colOf = (n) => (gs.find((q) => q.names.has(n)) || {}).col || "#2a3350";
    return { cls: "dark", html: `${head(s)}<div class="body"><div class="mp"><svg ${inn()} viewBox="0 0 ${n1(OW)} ${H}" style="width:${n1(OW)}px" role="img" aria-label="${alt}" font-family="Be Vietnam Pro, sans-serif"><svg x="0" y="0" width="${n1(OW)}" height="${H}" viewBox="0 0 ${vw} ${vh}">${Object.entries(PV).map(([n, p]) => `<path d="${p.d}" fill="${colOf(n)}" stroke="#0c1222" stroke-width="2.4" stroke-linejoin="round"/>`).join("")}${isl}</svg>${islLab}</svg><div>${s.stat ? `<div class="mpn" ${inn("pop")}>${f(s.stat.value)}</div><div class="nd" style="margin-bottom:40px" ${inn()}>${f(s.stat.label || "")}</div>` : ""}<div class="mpg">${gs.map((q) => `<div ${inn()}><i style="background:${q.col}"></i><b>${q.names.size}</b><span>${f(q.g.label)}</span></div>`).join("")}</div></div></div></div>${note(s.note || s.takeaway)}` };
  }
  // địa danh: bản đồ toàn quốc để định vị + khung phóng to có ghim đánh số, danh sách bên phải dùng cùng số
  const places = (s.places || []).slice(0, 4), hi = places.map((x) => find(x.name)).filter(Boolean), hiN = new Set(hi.map((h) => h[0]));
  const pts = hi.flatMap(([, p]) => [...p.d.matchAll(/(-?[\d.]+) (-?[\d.]+)/g)].map((m) => [+m[1], +m[2]])), ZW = 520, ZX = OW + 70;
  const [x0, y0, x1, y1] = pts.length ? [Math.min(...pts.map((q) => q[0])), Math.min(...pts.map((q) => q[1])), Math.max(...pts.map((q) => q[0])), Math.max(...pts.map((q) => q[1]))] : [0, 0, vw, vh];
  let bw = (x1 - x0) * 1.9 + 40, bh = (y1 - y0) * 1.9 + 40; if (bw / bh > ZW / H) bh = bw * H / ZW; else bw = bh * ZW / H;
  const zb = [(x0 + x1) / 2 - bw / 2, (y0 + y1) / 2 - bh / 2, bw, bh], rb = zb.map((v) => v * k);
  const prov = (sw) => Object.entries(PV).map(([n, p]) => `<path d="${p.d}" fill="${hiN.has(n) ? "#f6b93b" : "#2a3350"}" stroke="#0c1222" stroke-width="${n1(sw)}" stroke-linejoin="round"/>`).join("");
  const pins = places.map((x, i) => { const fd = find(x.name); return fd && fd[1].c ? { i, x: ZX + (fd[1].c[0] - zb[0]) / zb[2] * ZW, y: (fd[1].c[1] - zb[1]) / zb[3] * H } : null; }).filter(Boolean);
  const route = s.route ? pins.slice(1).map((q, j) => `<line x1="${n1(pins[j].x)}" y1="${n1(pins[j].y)}" x2="${n1(q.x)}" y2="${n1(q.y)}" stroke="#e2402a" stroke-width="7" stroke-dasharray="16 12"/>`).join("") : "";
  const svg = `<svg ${inn()} viewBox="0 0 ${n1(ZX + ZW + 4)} ${H}" style="width:${n1(ZX + ZW + 4)}px" role="img" aria-label="${alt}; khung phóng to: ${esc(places.map((x) => x.name).join(", "))}" font-family="Be Vietnam Pro, sans-serif"><svg x="0" y="0" width="${n1(OW)}" height="${H}" viewBox="0 0 ${vw} ${vh}">${prov(1.4)}${isl}</svg>${islLab}<rect x="${n1(rb[0])}" y="${n1(rb[1])}" width="${n1(rb[2])}" height="${n1(rb[3])}" fill="none" stroke="#e2402a" stroke-width="5"/><path d="M${n1(rb[0] + rb[2])},${n1(rb[1])} L${ZX},2 M${n1(rb[0] + rb[2])},${n1(rb[1] + rb[3])} L${ZX},${H - 2}" stroke="#e2402a" stroke-width="3" stroke-dasharray="10 8" fill="none"/><svg x="${n1(ZX)}" y="0" width="${ZW}" height="${H}" viewBox="${zb.map(n1).join(" ")}"><rect x="${n1(zb[0])}" y="${n1(zb[1])}" width="${n1(zb[2])}" height="${n1(zb[3])}" fill="#141c33"/>${prov(bw / 260)}</svg><rect x="${n1(ZX)}" y="2" width="${ZW}" height="${H - 4}" fill="none" stroke="#e2402a" stroke-width="5"/>${route}${pins.map((q) => `<circle cx="${n1(q.x)}" cy="${n1(q.y)}" r="34" fill="#e2402a" stroke="#fff" stroke-width="5"/><text x="${n1(q.x)}" y="${n1(q.y + 14)}" text-anchor="middle" font-family="Anton" font-size="40" fill="#fff">${q.i + 1}</text>`).join("")}</svg>`;
  return { cls: "dark", html: `${head(s)}<div class="body"><div class="mp">${svg}<div class="mpl">${places.map((x, i) => `<div ${inn()}><div class="pin">${i + 1}</div><div><b>${f(x.label || x.name)}</b><span>${f(x.note || "")}</span></div></div>`).join("")}</div></div></div>${note(s.note || s.takeaway)}` };
};

// ── bài giảng: trắc nghiệm, công thức, đề bài, lời giải ──
T.quiz = (s) => { const L = "ABCDEF", ans = typeof s.answer === "string" ? L.indexOf(s.answer.toUpperCase()) : s.answer; return { cls: s.reveal ? "light" : "dark", html: `${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}<h2 class="h ${plain(s.title).length > 54 ? "sm" : ""}" ${inn()}>${f(s.title)}</h2>${s.stem ? `<p class="sub" ${inn()}>${f(s.stem)}</p>` : ""}<div class="body"><div class="qz">${(s.options || []).map((o, i) => `<div class="card op ${s.reveal ? (i === ans ? "yes" : "x") : ""}" ${inn()}><span class="lt2">${L[i]}</span><div><b>${f(typeof o === "string" ? o : o.text)}</b>${s.reveal && s.whyNot?.[i] ? `<small>${f(s.whyNot[i])}</small>` : ""}</div></div>`).join("")}</div></div>${s.reveal ? note(s.why) : ""}` }; };
T.formula = (s) => { const terms = s.terms || []; return { cls: "dark", html: `${head(s)}<div class="body"><div class="fm ${terms.length > 3 ? "many" : ""}">${s.result ? `<div class="tm res" ${inn()}><b>${f(s.result.sym)}</b><span>${f(s.result.label)}</span></div><i>=</i>` : ""}${terms.map((x, i) => `${i ? `<i>${esc(x.op || "×")}</i>` : ""}<div class="tm ${s.focus === i ? "on" : ""}" ${inn()}><b>${f(x.sym)}</b><span>${f(x.label)}</span>${x.note ? `<small>${f(x.note)}</small>` : ""}</div>`).join("")}</div>${s.example ? `<p class="exm" ${inn()}>${f(s.example)}</p>` : ""}</div>${note(s.note)}` }; };
T.exercise = (s) => ({ cls: "light", html: `${head(s)}<div class="body"><div class="evd"><div class="doc" style="transform:rotate(-1deg)" ${inn()}><div class="dh">${f(s.label || "Đề bài")}</div><p class="pp">${f(s.prompt)}</p></div><div>${(s.given || []).length ? `<div class="lt" ${inn()}>Dữ kiện</div><div class="gv">${s.given.map((g) => `<div ${inn()}><span>${f(g.label)}</span><b>${f(g.value)}</b></div>`).join("")}</div>` : ""}${s.ask ? `<div class="ask" ${inn("pop")}>${f(s.ask)}</div>` : ""}</div></div></div>${note(s.hint || s.note)}` });
T.calc = (s) => ({ cls: "light", html: `${head(s)}<div class="body">${(s.given || []).length ? `<div class="giv" ${inn()}><b>Dữ kiện</b>${s.given.map((g) => `<span>${f(g.label)}: <strong>${f(g.value)}</strong></span>`).join("")}</div>` : ""}<div class="clc">${(s.steps || []).map((x, i) => `<div class="st" ${inn()}><span class="nb">${i + 1}</span><div><b>${f(x.label)}</b><span>${f(x.expr || "")}</span></div><strong>${f(x.value)}</strong></div>`).join("")}${s.answer ? `<div class="ans" ${inn("pop")}><div><b>${f(s.answer.value)}</b> ${f(s.answer.unit || "")}</div><span>${f(s.answer.label || "")}</span></div>` : ""}</div></div>${note(s.note)}` });
T.journey = (s) => { const st = s.stages || []; return { cls: "light", html: `${head(s)}<div class="body">${s.who ? `<div class="lt" ${inn()}><b style="color:var(--fg)">${f(s.who.name)}</b> — ${f(s.who.sub || "")}</div>` : ""}<div class="evs" style="--n:${Math.min(Math.max(st.length, 2), 6)};gap:22px">${st.map((e, i) => `<div class="card ev ${s.focus === i ? "hot" : ""}" ${inn()}><div class="w">${f(e.when)}</div><div class="d" style="font-size:58px">${ico(e.icon)}</div><div class="t" style="font-size:28px">${f(e.event)}</div>${e.link ? `<div class="tag" style="margin-top:14px">${f(e.link)}</div>` : ""}</div>`).join("")}</div></div>${note(s.note)}` }; };
T.cheatsheet = (s) => { const cols = s.cols || [], rows = s.rows || []; return { cls: "light", html: `${head(s)}<div class="body"><table ${inn()}><tr><th></th>${cols.map((c) => `<th>${f(c.name)}</th>`).join("")}</tr>${rows.map((r, i) => `<tr><td class="q" style="font-size:38px;width:230px">${f(r.label)}</td>${cols.map((c) => `<td style="font-size:${cols.length <= 3 ? 34 : cols.length <= 5 ? 30 : 26}px">${f(c.cells?.[i] ?? "")}</td>`).join("")}</tr>`).join("")}</table></div>${note(s.note)}` }; };
T.changelog = (s) => { const lab = { changed: "Đổi", new: "Mới", removed: "Bỏ", kept: "Giữ" }; return { cls: "light", html: `${head(s)}<div class="body"><table ${inn()}><tr><th>${f(s.colTopic || "")}</th><th>${f(s.colOld || "Cũ")}</th><th>${f(s.colNew || "Mới")}</th><th></th></tr>${(s.rows || []).map((r, i) => `<tr class="${s.focus === i ? "on" : ""}"><td style="font-weight:800">${f(r.topic)}</td><td style="color:var(--mut)">${r.status === "kept" ? f(r.old) : `<s>${f(r.old)}</s>`}</td><td style="font-weight:800">${f(r.new)}</td><td><span class="tag st-${esc(r.status)}">${lab[r.status] || ""}</span></td></tr>`).join("")}</table></div>${note(s.note)}` }; };
// ── sơ đồ khái niệm ──
T.pyramid = (s) => { const lv = s.levels || []; return { cls: "light", html: `${head(s)}<div class="body"><div class="py ${lv.length >= 4 ? "c5" : ""}">${lv.map((l, i) => `<div class="${s.focus === i ? "on" : ""}" style="width:${(40 + (i / Math.max(1, lv.length - 1)) * 60).toFixed(1)}%" ${inn()}><b>${f(l.head)}</b>${l.text ? `<span>${f(l.text)}</span>` : ""}</div>`).join("")}</div></div>${note(s.note)}` }; };
T.matrix = (s) => { const c = s.cells || []; return { cls: "light", html: `${head(s)}<div class="body"><div class="mx"><div class="yl">${f(s.y?.label || "")}</div><div class="yh">${f(s.y?.hi || "")}</div><div class="ylo">${f(s.y?.lo || "")}</div>${c.slice(0, 4).map((x, i) => `<div class="card c${i} ${x.tone || ""}" ${inn()}><b>${f(x.head)}</b><span>${f(x.text || "")}</span></div>`).join("")}<div class="xlo">${f(s.x?.lo || "")}</div><div class="xh">${f(s.x?.hi || "")}</div><div class="xl">${f(s.x?.label || "")}</div></div></div>${note(s.note)}` }; };
T.venn = (s) => { const col = (d, c) => `<div class="card ${c}" ${inn()}><h3>${f(d?.label || "")}</h3><ul class="gl">${(d?.items || []).map((x) => `<li>${f(x)}</li>`).join("")}</ul></div>`; return { cls: "light", html: `${head(s)}<div class="body"><div class="vn">${col(s.left, "")}${col(s.both, "mid")}${col(s.right, "")}</div></div>${note(s.note)}` }; };
T.tree = (s) => { const br = s.branches || []; return { cls: "light", html: `${head(s)}<div class="body">${s.root ? `<div class="rootq" ${inn()}>${f(s.root.q)}${s.root.src ? `<small>${f(s.root.src)}</small>` : ""}</div>` : ""}<div class="fk" style="grid-template-columns:repeat(${Math.max(br.length, 2)},1fr)">${br.map((b, i) => `<div class="card br ${b.tone || ""} ${s.focus === i ? "on" : ""}" ${inn()}><div class="tg">${f(b.when)}</div><h3>${f(b.head)}</h3><p>${f(b.text || "")}</p></div>`).join("")}</div></div>${note(s.note)}` }; };
T.hub = (s) => { const it = s.items || []; return { cls: "light", html: `${head(s)}<div class="body"><div class="hb">${s.center ? `<div class="ctr" ${inn("pop")}>${ico(s.center.icon)}<b>${f(s.center.label)}</b></div>` : ""}<div class="cg" style="--n:2;gap:26px">${it.map((x) => `<div class="card" style="padding:22px 26px" ${inn()}><div class="w" style="display:flex;gap:14px;align-items:center;color:var(--fg);font-size:34px">${ico(x.icon)}${f(x.head)}</div><div class="d" style="font-size:27px;margin-top:8px">${f(x.text || "")}</div></div>`).join("")}</div></div></div>${note(s.note)}` }; };
T.bento = (s) => { const c = s.cells || s.items || []; return { cls: "light", html: `${head(s)}<div class="body"><div class="bt">${c.map((x, i) => `<div class="card ${i === 0 ? "main" : ""}" ${inn()}>${ico(x.icon)}${x.value ? `<div class="v">${f(x.value)}</div>` : ""}<b>${f(x.head)}</b>${x.text ? `<span>${f(x.text)}</span>` : ""}${(x.items || []).length ? `<span>${x.items.map(f).join(", ")}</span>` : ""}</div>`).join("")}</div></div>${note(s.note || s.takeaway)}` }; };
T.share = (s) => { const p = Math.round(+s.pct || 0); return { cls: "dark", html: `${head(s)}<div class="body"><div class="bn"><div><div class="n" style="font-size:380px" ${inn("pop")}>${p}<small style="font-size:160px">%</small></div><div class="nd" ${inn()}>${f(s.label || "")}</div></div><div><div class="wf" ${inn()}>${Array.from({ length: 100 }, (_, i) => `<i class="${i < p ? "on" : ""}"></i>`).join("")}</div>${(s.legend || []).length ? `<div class="dl"><span>■ ${f(s.legend[0])}</span><span>□ ${f(s.legend[1] || "")}</span></div>` : ""}${(s.items || []).length ? `<ul class="shi">${s.items.slice(0, 3).map((x) => `<li ${inn()}>${ico(x.icon)}<div><b>${f(x.head)}</b>${x.text ? `<span>${f(x.text)}</span>` : ""}</div></li>`).join("")}</ul>` : ""}</div></div></div>${note(s.note)}` }; };
T.deadline = (s) => { const a = dmy(s.from), b = dmy(s.to), td = s.today ? dmy(s.today) : null, pc = td != null ? Math.max(0, Math.min(100, (td - a) / (b - a) * 100)) : 0; return { cls: "dark", html: `${head(s)}<div class="body"><div class="bn"><div><div class="n" style="font-size:300px" ${inn("pop")}>${f(s.display || "")}</div><div class="nd" ${inn()}>${f(s.label || "")}</div></div><div ${inn()}><div class="dbar"><i style="width:${pc.toFixed(1)}%"></i></div><div class="dl"><span><b>${esc(s.from)}</b><br>${f(s.fromLabel || "")}</span><span style="text-align:right"><b>${esc(s.to)}</b><br>${f(s.toLabel || "")}</span></div>${(s.markers || []).map((m) => `<p class="sub" style="margin-top:24px;font-size:27px">${esc(m.date)} — ${f(m.label)}</p>`).join("")}</div></div></div>${note(s.note)}` }; };
T.redline = (s) => { let body; try { body = require("../engine/codeart").wordDiff(plain(s.old?.text || ""), plain(s.new?.text || "")).map((p) => (p.t === "ins" ? `<ins>${esc(p.v)}</ins>` : p.t === "del" ? `<del>${esc(p.v)}</del>` : esc(p.v))).join(""); } catch { body = f(s.new?.text || ""); } return { cls: "light", html: `${head(s)}<div class="body"><div class="lt" ${inn()}><span class="tag" style="background:var(--red);color:#fff">${f(s.old?.label || "Bản cũ")}</span> → <span class="tag" style="background:var(--green);color:#fff">${f(s.new?.label || "Bản mới")}</span></div><div class="doc rl" style="transform:none" ${inn()}>${body}</div></div>${note(s.note)}` }; };
T.isotype = (s) => { const u = s.unit?.value || 1; return { cls: "light", html: `${head(s)}<div class="body"><div class="iso">${(s.rows || []).map((r) => { const n = Math.round(r.value / u), lost = Math.round((r.lost || 0) / u); return `<div ${inn()}><div class="il"><b>${f(r.label)}</b><span>${f(r.display || `${r.value} ${s.unit?.short || ""}`)}</span></div><div class="ig">${Array.from({ length: n }, (_, i) => `<i class="${i >= n - lost ? "lost" : ""}"></i>`).join("")}</div></div>`; }).join("")}</div>${s.unit ? `<p class="note" ${inn()}>Mỗi ô = ${esc(s.unit.value)} ${f(s.unit.label)}${s.lostLabel ? `; ô nét đứt = ${f(s.lostLabel)}` : ""}</p>` : ""}</div>` }; };
T.funnel = (s) => { const col = (arr) => `<div class="fc">${(arr || []).map((x) => `<div class="card ${x.focus ? "hot" : ""}" ${inn()}><b>${f(x.display || "")}</b><span>${f(x.label)}</span></div>`).join("")}</div>`; return { cls: "light", html: `${head(s)}<div class="body">${s.inLabel || s.outLabel || s.unit ? `<div class="fn fn-h"><span>${f(s.inLabel || "")}</span><i></i><span>${s.unit ? `Đơn vị: ${f(s.unit)}` : ""}</span><i></i><span>${f(s.outLabel || "")}</span></div>` : ""}<div class="fn">${col(s.sources)}<div class="arw">→</div><div class="pool" ${inn("pop")}><b>${f(s.pool?.label || "")}</b><span>${f(s.pool?.sub || "")}</span></div><div class="arw">→</div>${col(s.uses)}</div></div>${note(s.note)}` }; };
// ── bố cục ảnh ──
const fig = (ctx, p, cap) => `<figure ${inn()}><div class="pi" style="background-image:url('${ctx.img(p)}')"></div>${cap ? `<figcaption>${cap}</figcaption>` : ""}</figure>`;
T.mosaic = T.gallery = (s, deck, ctx) => { const ph = s.photos || []; return { cls: "dark", html: `${head(s)}<div class="body"><div class="pg" style="--n:${Math.min(Math.max(ph.length, 2), 4)}">${ph.map((x) => fig(ctx, x.photo, f(x.caption || ""))).join("")}</div></div>${note(s.note)}` }; };
T.photostrip = (s, deck, ctx) => { const it = s.items || []; return { cls: "dark", html: `${head(s)}<div class="body"><div class="pg" style="--n:${Math.min(Math.max(it.length, 2), 5)}">${it.map((x) => fig(ctx, x.photo, `<small>${f(x.date || "")}</small><b>${f(x.head || "")}</b>${f(x.text || "")}`)).join("")}</div></div>${note(s.note)}` }; };
T.beforeafter = (s, deck, ctx) => { const side = (d) => `<figure ${inn()}><div class="pi" style="background-image:url('${ctx.img(d?.photo)}')"><span class="tag">${f(d?.label || "")}${d?.date ? ` — ${f(d.date)}` : ""}</span></div><figcaption>${f(d?.caption || "")}</figcaption></figure>`; return { cls: "dark", html: `${head(s)}<div class="body"><div class="pg" style="--n:2">${side(s.before)}${side(s.after)}</div></div>${note(s.note)}` }; };
T.photostats = T.split = (s, deck, ctx) => { const st = s.stats, it = s.items, right = s.side === "right"; return { cls: `light sp ${right ? "sp-r" : "sp-l"}`, html: `<div class="sp-ph" style="background-image:url('${ctx.img(s.photo)}')"></div><div class="sp-in">${head(s)}${s.sub ? `<p class="sub" ${inn()}>${f(s.sub)}</p>` : ""}<div class="body">${st ? `<div class="spst">${st.map((x) => `<div ${inn()}><b class="${x.tone || ""}">${f(x.value)}</b><span>${f(x.label)}${x.desc ? `<small>${f(x.desc)}</small>` : ""}</span></div>`).join("")}</div>` : ""}${it ? `<ul class="gl">${it.map((x) => `<li ${inn()}><b>${f(x.head)}</b><span>${f(x.text || "")}</span></li>`).join("")}</ul>` : ""}</div>${note(s.note)}</div>` }; };
T.frame = (s, deck, ctx) => { const pt = s.points || []; return { cls: "light", html: `${head(s)}<div class="body"><div class="evd" style="grid-template-columns:1.1fr 1fr"><div class="fr" ${inn()}><div class="pi" style="background-image:url('${ctx.img(s.photo)}')"></div>${pt.map((p, i) => `<span class="pinp" style="left:${(p.x * 100).toFixed(1)}%;top:${(p.y * 100).toFixed(1)}%">${i + 1}</span>`).join("")}</div><ol class="nl">${pt.map((p) => `<li ${inn()}><div><b>${f(p.head)}</b><span>${f(p.text || "")}</span></div></li>`).join("")}</ol></div></div>${note(s.note)}` }; };

T.iso = (s) => {
  const obs = (s.objects || []).slice(0, 8), anyF = obs.some((o) => o.focus);
  const calm = { base: "e9dfc6", baseLine: "8d8672", top: "ddd3ba", left: "e6dcc4", right: "c4baa0", roof: "8d8672", roof2: "5b5443", door: "5b5443", window: "a59d87", leaf: "a9b99a", line: "0c1222", pin: "e2402a" };
  const hot = { base: "fbe3a8", baseLine: "0c1222", top: "f9d27a", left: "fff6de", right: "f6b93b", roof: "e2402a", roof2: "0c1222", door: "0c1222", window: "f6b93b", leaf: "2c9566", line: "0c1222", pin: "e2402a" };
  const labs = obs.map((o, i) => ({ o, i })).filter((q) => q.o.label), SW = labs.length ? 1110 : 1700, SH = 640, LH = 136, LX = SW + 70;
  let sc; try { sc = require("../engine/codeart").isoScene(obs, SW / 100, SH / 100, anyF ? { ...calm, f: hot } : hot); } catch { return T.generic(s); }
  const order = labs.map((q) => ({ ...q, ax: sc.anchors[q.i][0] * 100, ay: sc.anchors[q.i][1] * 100 })).sort((a, b) => a.ay - b.ay);
  let prev = -1e9; order.forEach((q, k) => { q.ly = Math.min(Math.max(q.ay - 30, prev + LH, 0), SH - LH - (order.length - 1 - k) * LH); prev = q.ly; });
  const cl = (q) => (q.o.focus || !anyF ? "#e2402a" : "#0c1222");
  const lines = order.map((q) => `<path d="M${q.ax.toFixed(1)},${q.ay.toFixed(1)} V${(q.ly + 28).toFixed(1)} H${LX - 16}" fill="none" stroke="${cl(q)}" stroke-width="5"/>`).join("");
  const dots = order.map((q) => `<circle cx="${q.ax.toFixed(1)}" cy="${q.ay.toFixed(1)}" r="11" fill="${cl(q)}" stroke="#fff" stroke-width="4"/>`).join("");
  const scene = sc.svg.replace("<svg ", `<svg x="0" y="0" width="${SW}" height="${SH}" `).replace(/stroke-width="2"/g, 'stroke-width="3.5"');
  return { cls: "light", html: `${head(s)}<div class="body"><div class="isc" role="img" aria-label="${esc("Hình isometric: " + obs.map((o) => o.label || o.kind).join(", "))}" ${inn()}><svg viewBox="0 0 1700 ${SH}">${lines}${scene}${dots}</svg>${order.map((q) => `<div class="isl ${q.o.focus ? "on" : ""}" style="left:${LX}px;top:${q.ly.toFixed(0)}px"><b>${f(q.o.label)}</b>${q.o.sub ? `<span>${f(q.o.sub)}</span>` : ""}</div>`).join("")}</div></div>${note(s.note)}` };
};

// ── cặp điều kiện – hệ quả, ảnh dẫn chuyện, đồ vật giấy tờ (hoá đơn, sao kê, biên bản, lịch, sơ đồ thửa) ──
const pct = (v) => ((+v || 0) * 100).toFixed(1) + "%";
const lis = (arr) => `<ul class="gl">${(arr || []).map((x) => `<li ${inn()}><b>${f(x.head)}</b><span>${f(x.text || "")}</span></li>`).join("")}</ul>`;
T.match = (s) => { const g = []; (s.pairs || []).forEach((p, i) => { const last = g[g.length - 1]; if (last && last.left === p.left) last.r.push({ ...p, i }); else g.push({ left: p.left, r: [{ ...p, i }] }); });  // hai hàng cùng vế trái → gộp một ô
  return { cls: "light", html: `${head(s)}<div class="body"><div class="mt"><div class="mth"><span>${f(s.colL || "")}</span><i></i><span>${f(s.colR || "")}</span></div>${g.map((x) => `<div class="mtr" ${inn()}><div class="ml">${f(x.left)}</div><div class="ma">→</div><div class="mr">${x.r.map((p) => `<div class="${s.focus === p.i ? "on" : ""}"><b>${f(p.right)}</b>${p.note ? `<small>${f(p.note)}</small>` : ""}</div>`).join("")}</div></div>`).join("")}</div></div>${note(s.note)}` }; };
T.headline = (s, deck, ctx) => { const p = ctx.img(s.photo); return { cls: "dark pho hdl", bare: true, html: `${p ? `<div class="img" style="background-image:url('${p}')"></div>` : ""}<div class="tint"></div><div class="in">${s.kicker ? `<div class="k" ${inn()}>${f(s.kicker)}</div>` : ""}<h2 class="h" ${inn()}>${(s.lines || [s.title || ""]).map(f).join("<br>")}</h2>${s.sub ? `<p class="sub" ${inn()}>${f(s.sub)}</p>` : ""}${s.note ? `<p class="note" ${inn()}>${f(s.note)}</p>` : ""}</div>` }; };
T.lens = (s, deck, ctx) => { const fo = s.focus || {}; return { cls: "light", html: `${head(s)}<div class="body"><div class="evd" style="grid-template-columns:1.15fr 1fr"><div class="fr lz" ${inn()}><div class="pi" style="background-image:url('${ctx.img(s.photo)}')"></div><span class="ring" style="left:${pct(fo.x ?? 0.5)};top:${pct(fo.y ?? 0.5)};width:${pct((fo.r || 0.12) * 2)}"></span>${fo.label ? `<span class="tag lzl">${f(fo.label)}</span>` : ""}</div>${lis(s.items)}</div></div>${note(s.note)}` }; };
T.collage = (s, deck, ctx) => { const ph = (s.photos || []).slice(0, 3), R = [-4, 3, -2]; return { cls: "light", html: `${head(s)}<div class="body"><div class="evd" style="grid-template-columns:1.2fr 1fr"><div class="clg n${ph.length}">${ph.map((x, i) => `<figure style="rotate:${R[i]}deg" ${inn()}><div class="pi" style="background-image:url('${ctx.img(x.photo)}')"></div>${x.caption ? `<figcaption>${f(x.caption)}</figcaption>` : ""}</figure>`).join("")}</div>${lis(s.items)}</div></div>${note(s.note)}` }; };
T.sheet = (s) => { const rows = s.rows || [], mx = Math.max(1, ...rows.map((r) => Math.abs(+r.value || 0))); return { cls: "light", html: `${head(s)}<div class="body"><div class="sh2 ${rows.length > 7 ? "many" : ""}">${(s.cols || []).length || s.unit ? `<div class="sh-h"><span>${f((s.cols || [])[0] || "")}</span><span></span><span>${f((s.cols || [])[1] || "")}${s.unit ? ` (${f(s.unit)})` : ""}</span><span>${f((s.cols || [])[2] || "")}</span></div>` : ""}${rows.map((r) => `<div class="${r.focus ? "on" : ""} ${r.tone || ""}" ${inn()}><b>${f(r.label)}</b><div class="bx"><i style="width:${Math.max(1, Math.abs(+r.value || 0) / mx * 100).toFixed(1)}%"></i></div><strong>${f(r.display ?? r.value)}</strong><span>${f(r.note || "")}</span></div>`).join("")}</div></div>${note(s.note)}` }; };
T.calendar = (s) => { const days = Math.min(31, Math.max(28, +s.days || 30)), st = Math.min(7, Math.max(1, +s.startDay || 1)), mk = (s.marks || []).slice(0, 4);  // startDay: 1 = thứ Hai … 7 = Chủ nhật
  const cell = (d) => { const j = mk.findIndex((m) => d >= m.from && d <= m.to); return `<div class="${j >= 0 ? `m m${j} ${mk[j].tone || ""}` : ""} ${(st - 1 + d - 1) % 7 === 6 ? "cn" : ""}">${d}</div>`; };
  return { cls: "light", html: `${head(s)}<div class="body"><div class="cal"><div class="card cgd" ${inn()}><div class="cm">${f(s.month || "")}</div><div class="cw">${["T2", "T3", "T4", "T5", "T6", "T7", "CN"].map((d) => `<span>${d}</span>`).join("")}</div><div class="cdd">${`<div class="e"></div>`.repeat(st - 1)}${Array.from({ length: days }, (_, i) => cell(i + 1)).join("")}</div></div><div class="cms">${mk.map((m, j) => `<div class="card" ${inn()}><i class="m${j} ${m.tone || ""}"></i><div><b>${m.to - m.from + 1} ngày</b><span>${f(m.label)}</span><small>Từ ngày ${+m.from} đến ngày ${+m.to}</small></div></div>`).join("")}</div></div></div>${note(s.note)}` }; };
T.riskbar = (s) => { const st = (s.stages || []).slice(0, 7), rows = (s.rows || []).slice(0, 8), n = Math.max(1, st.length), lg = s.legend || [];
  return { cls: "light", html: `${head(s)}<div class="body"><div class="rk" style="--n:${n}"><div class="rkh"><span></span><div>${st.map((x) => `<span>${f(x)}</span>`).join("")}</div></div>${rows.map((r) => { const at = Math.max(0, Math.min(n, +r.at || 0)), pay = Math.max(at, Math.min(n, +r.pay || 0)); return `<div class="rkr" ${inn()}><div><b>${f(r.label)}</b><small>${f(r.sub || "")}</small></div><div class="rkb"><i class="a" style="width:${(at / n * 100).toFixed(1)}%"></i>${pay > at ? `<i class="p" style="left:${(at / n * 100).toFixed(1)}%;width:${((pay - at) / n * 100).toFixed(1)}%"></i>` : ""}</div></div>`; }).join("")}${lg.length ? `<div class="rkl">${lg.slice(0, 3).map((x, i) => `<span><i class="l${i}"></i>${f(x)}</span>`).join("")}</div>` : ""}</div></div>${note(s.note)}` }; };
T.plan = (s) => { const H = 520, Wd = Math.max(260, Math.min(900, H * (+s.ratio || 0.7))); return { cls: "light", html: `${head(s)}<div class="body"><div class="evd" style="grid-template-columns:auto 1fr;gap:110px"><div class="pl" style="width:${Wd.toFixed(0)}px;height:${H}px" ${inn()}>${(s.zones || []).map((z) => `<div class="z ${z.tone || ""}" style="left:${pct(z.x)};top:${pct(z.y)};width:${pct(z.w)};height:${pct(z.h)}"><span>${f(z.label)}</span></div>`).join("")}${s.width ? `<span class="dw">${f(s.width)}</span>` : ""}${s.height ? `<span class="dh2">${f(s.height)}</span>` : ""}</div>${lis(s.items)}</div></div>${note(s.note)}` }; };
T.receipt = (s) => { const row = (x, c = "") => (x ? `<div class="${c} ${x.focus ? "on" : ""}"><span>${f(x.label)}</span><b>${f(x.display ?? x.value)}</b></div>` : "");
  return { cls: "light", html: `${head(s)}<div class="body"><div class="evd" style="grid-template-columns:auto 1fr;gap:110px"><div class="rcw" ${inn()}><div class="rcp"><div class="rh">${f(s.head || "Hoá đơn")}</div>${(s.items || []).map((x) => row(x)).join("")}${row(s.sub, "sb")}${row(s.tax, "tx")}${row(s.total, "tt")}${s.unit ? `<small>Đơn vị: ${f(s.unit)}</small>` : ""}</div></div>${lis(s.points)}</div></div>${note(s.note)}` }; };
T.account = (s) => { const vn = (v) => (v > 0 ? "+" : "−") + Math.abs(v).toLocaleString("vi-VN"), oc = (lab, v) => (v != null ? `<tr class="oc"><td></td><td>${lab}</td><td></td><td style="text-align:right">${f(v)}</td></tr>` : "");
  return { cls: "light", html: `${head(s)}<div class="body"><table class="acc" ${inn()}><tr><th>${f((s.cols || [])[0] || "Ngày")}</th><th>${f((s.cols || [])[1] || "Nội dung")}</th><th style="text-align:right">${f((s.cols || [])[2] || "Số tiền")}${s.unit ? ` (${f(s.unit)})` : ""}</th><th style="text-align:right">${f((s.cols || [])[3] || "Số dư")}</th></tr>${oc("Số dư đầu kỳ", s.open)}${(s.rows || []).map((r) => `<tr class="${r.focus ? "on" : ""}"><td>${f(r.date)}</td><td style="font-weight:800">${f(r.desc)}</td><td class="am ${+r.amount < 0 ? "neg" : "pos"}">${f(r.display ?? vn(+r.amount || 0))}</td><td style="text-align:right">${f(r.balance ?? "")}</td></tr>`).join("")}${oc("Số dư cuối kỳ", s.close)}</table></div>${note(s.note)}` }; };
T.captable = (s) => { const hs = s.holders || [], th = s.thresholds || [], rest = Math.max(0, 100 - hs.reduce((a, h) => a + (+h.pct || 0), 0)), C = ["var(--ink)", "#55607e", "#8d8672", "#b8ad8f"]; let k = 0, d0 = 0;
  // ngưỡng xếp tăng dần, mỗi ngưỡng một hàng nhãn thấp dần; đường nét đứt bắt đầu từ hàng nhãn CỦA NÓ → không cắt nhãn ngưỡng nhỏ hơn (nhãn đó nằm hàng trên, bên trái)
  const ths = [...th].sort((a, b) => (+a.pct || 0) - (+b.pct || 0)), hang = Math.min(40, Math.floor(100 / Math.max(1, ths.length)));
  // số % trong đoạn: ngưỡng rơi gần giữa đoạn thì đẩy số sang phía xa đường ngưỡng (không để nét đứt chạy qua chữ số)
  const canSo = (a, w) => { const t = ths.map((x) => +x.pct || 0).find((v) => v > a + 1 && v < a + w - 1); if (t === undefined) return ""; return t > a + w / 2 ? ";justify-content:flex-start;padding-left:22px" : ";justify-content:flex-end;padding-right:22px"; };
  return { cls: "light", html: `${head(s)}<div class="body">${s.company ? `<div class="lt" ${inn()}>${f(s.company)}</div>` : ""}<div class="cpb" ${inn()}>${hs.map((h) => { const a = d0, w = +h.pct || 0; d0 += w; return `<i style="width:${w}%;background:${h.focus ? "var(--red)" : C[k++ % 4]}${canSo(a, w)}"><b>${w}%</b></i>`; }).join("")}${rest ? `<i style="width:${rest}%" class="rs"></i>` : ""}${ths.map((x, j) => `<span class="thr" style="left:${+x.pct || 0}%;top:${-106 + j * hang}px"><em>${f(x.label)}</em></span>`).join("")}</div><div class="cph" style="--n:${Math.min(hs.length + (rest ? 1 : 0), 6)}">${hs.map((h) => `<div class="${h.focus ? "on" : ""}" ${inn()}><b>${+h.pct || 0}%</b><span>${f(h.name)}</span><small>${f(h.sub || "")}</small></div>`).join("")}${rest ? `<div class="rs" ${inn()}><b>${+rest.toFixed(1)}%</b><span>Còn lại</span></div>` : ""}</div></div>${note(s.note)}` }; };
T.record = (s) => { const SG = { signed: ["Đã ký", "s-ok"], refused: ["Từ chối ký", "s-no"], absent: ["Vắng mặt", "s-ab"] };
  return { cls: "light", html: `${head(s)}<div class="body"><div class="evd" style="grid-template-columns:1.2fr 1fr"><div ${inn()}><div class="doc rc" style="transform:rotate(-1deg)"><div class="dh">${f(s.head || "Biên bản")}</div>${(s.fields || []).map((x) => `<div class="fd ${x.tone || ""}"><span>${f(x.label)}</span><b>${f(x.value)}</b></div>`).join("")}${(s.signs || []).length ? `<div class="sg">${s.signs.map((x) => { const [lab, c] = SG[x.state] || [x.state || "", "s-ab"]; return `<div class="${c}"><small>${f(x.role)}</small><b>${esc(lab)}</b></div>`; }).join("")}</div>` : ""}</div></div>${lis(s.points)}</div></div>${note(s.note)}` }; };

// type chưa có mẫu riêng: tiêu đề + mọi danh sách tìm thấy, để deck vẫn ra đủ slide; build in tên type để biết
T.generic = (s) => {
  const lists = ["items", "rows", "steps", "events", "conds"].map((k) => s[k]).filter(Array.isArray).flat();
  const row = (x) => typeof x === "string" ? `<li ${inn()}>${f(x)}</li>` : `<li ${inn()}><b>${f(x.head || x.name || x.title || x.label || x.q || "")}</b><span>${f([x.desc, x.text, x.value, x.who, x.a].filter(Boolean).join(" — "))}</span></li>`;
  return { cls: "light", html: `${head(s)}<div class="body">${s.text || s.sub ? `<p class="sub" style="margin-bottom:26px" ${inn()}>${f(s.text || s.sub)}</p>` : ""}<ul class="gl">${lists.slice(0, 7).map(row).join("")}</ul></div>${note(s.note || s.takeaway || s.footer)}` };
};

// bọc một khối mẫu thành slide: thanh tiến độ, tên bài, số trang (mẫu "bare" tự lo toàn bộ mặt slide)
function wrap(out, slide, deck, i, n) {
  const chrome = out.bare ? "" : `<div class="prog" style="width:${((i + 1) / n * 100).toFixed(1)}%"></div><div class="bar"><span>${esc(deck.meta?.short || deck.meta?.title || "")}</span><span class="cnt">${String(i + 1).padStart(2, "0")}<small> / ${n}</small></span></div>`;
  return `<section class="s ${out.cls}" data-type="${esc(slide.type)}" data-title="${esc(plain(slide.title || ""))}">${chrome}${out.html}</section>`;
}
function render(slide, deck, ctx, i, n) {
  I = 0;
  const fn = T[slide.type], out = (fn || T.generic)(slide, deck, ctx);
  // note / takeaway: validate.js cho phép, nhưng nhiều mẫu không vẽ (28/32 type từng bỏ mất takeaway, isotype / quote / quiz bỏ note) →
  // vẽ ở chân slide — chỗ cố định của câu chú thích; takeaway thành dải "Ghi nhớ" (vạch nhấn + nhãn) ở cùng chỗ trên mọi slide
  if (!out.bare && typeof slide.sub === "string" && slide.sub.trim() && !out.html.includes(f(slide.sub)) && out.html.includes("</h2>")) out.html = out.html.replace("</h2>", `</h2><p class="sub hsub" ${inn()}>${f(slide.sub)}</p>`);   // cards / stats… từng bỏ dòng phụ (đơn vị, phạm vi) dưới tiêu đề
  // đơn vị (unit dạng chuỗi): mẫu nào chưa in ra (biểu đồ bar / line / step… chỉ gantt in) thì ghi ở dòng phụ dưới tiêu đề — số không đơn vị là số vô nghĩa
  if (!out.bare && typeof slide.unit === "string" && slide.unit.trim() && !out.html.includes(f(slide.unit)) && out.html.includes("</h2>")) {
    const dv = `Đơn vị: ${f(slide.unit)}`; out.html = out.html.includes('class="sub hsub"') ? out.html.replace(/(<p class="sub hsub"[^>]*>)([\s\S]*?)<\/p>/, `$1$2 · ${dv}</p>`) : out.html.replace("</h2>", `</h2><p class="sub hsub" ${inn()}>${dv}</p>`); }
  if (!out.bare) {
    if (typeof slide.takeaway === "string" && slide.takeaway.trim()) { const gn = `<p class="note gn" ${inn()}><b class="gn-t">Ghi nhớ</b>${f(slide.takeaway)}</p>`;
      const k = out.html.lastIndexOf(`>${f(slide.takeaway)}</p>`);
      const a = k >= 0 ? out.html.lastIndexOf('<p class="note"', k) : -1;
      if (a >= 0 && !out.html.slice(a, k).includes("</p>")) out.html = out.html.slice(0, a) + gn + out.html.slice(k + f(slide.takeaway).length + 5);   // mẫu đã vẽ takeaway như chú thích thường → đổi thành dải
      else out.html += gn; }
    else if (typeof slide.note === "string" && slide.note.trim() && !out.html.includes(f(slide.note))) out.html += note(slide.note);
  }
  return { html: wrap(out, slide, deck, i, n), generic: !fn };
}
// kit: các hàm dựng chung, để tầng hình ảnh (hinh/canh.js) viết thêm mẫu cùng giọng với bộ mẫu này
module.exports = { render, wrap, plain, TYPES: Object.keys(T).filter((k) => k !== "generic" && !/Chu$/.test(k)), kit: { esc, f, head, note, inn, ico, reset: () => { I = 0; } } };
